"use client";

import Link from "next/link";
import { FormEvent, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import {
  ArrowLeft, ArrowRight, CalendarClock, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft,
  ChevronRight, Clock3, CreditCard, Download, FileText, Filter, Mail, MapPin, MoreHorizontal,
  Phone, Plus, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, UserRound, Users, X,
} from "lucide-react";
import {
  bookingStatusLabel, bookingStatusTone, calculateBookingTotals, getAvailableSlots,
} from "@invoice-monorepo/booking";
import type { BookingRecord, BookingStatus } from "@invoice-monorepo/booking";
import { createCustomer, createService } from "@invoice-monorepo/booking/api";
import { createClient } from "@/lib/supabase/client";
import { useBookingData } from "@/lib/booking-context";
import { EmptyState, PageHeader, QuickAction, SectionHeader, StatCard, StatusBadge } from "@invoice-monorepo/operix-ui";

const dateFormatter = new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "short", year: "numeric" });
const dayFormatter = new Intl.DateTimeFormat("en-GB", { weekday: "short", day: "numeric", month: "short" });
const timeFormatter = new Intl.DateTimeFormat("en-GB", { hour: "2-digit", minute: "2-digit", hour12: false });
const currencyFormatter = new Intl.NumberFormat("en-GB", { style: "currency", currency: "EUR", maximumFractionDigits: 0 });

function money(amount: number, currency = "EUR") {
  return new Intl.NumberFormat("en-GB", { style: "currency", currency, maximumFractionDigits: 0 }).format(amount || 0);
}
function dateLabel(value: string) { return dateFormatter.format(new Date(value)); }
function dayLabel(value: string) { return dayFormatter.format(new Date(value)); }
function timeLabel(value: string) { return timeFormatter.format(new Date(value)); }
function initials(name: string) { return name.split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase(); }
function dateInputValue(date = new Date()) { return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 10); }
function localIso(date: string, time: string) { return new Date(`${date}T${time}:00`).toISOString(); }
function localIsoAfter(date: string, time: string, minutes: number) { return new Date(new Date(`${date}T${time}:00`).getTime() + minutes * 60000).toISOString(); }

function periodDelta(current: number, previous: number) {
  if (previous === 0) return current === 0 ? "0%" : "New";
  const value = Math.round(((current - previous) / previous) * 1000) / 10;
  return (value > 0 ? "+" : "") + value + "%";
}

export function DashboardView() {
  const { bookings, company, profile, services, loading } = useBookingData();
  const todayKey = dateInputValue();
  const todayBookings = bookings.filter((booking) => dateInputValue(new Date(booking.starts_at)) === todayKey && booking.status !== "cancelled");
  const upcoming = bookings.filter((booking) => new Date(booking.starts_at) >= new Date() && !["cancelled", "completed"].includes(booking.status)).slice(0, 5);
  const completed = bookings.filter((booking) => booking.status === "completed");
  const cancelled = bookings.filter((booking) => booking.status === "cancelled");
  const revenue = completed.reduce((sum, booking) => sum + Number(booking.total_amount || 0), 0);
  const currency = company?.currency || "EUR";
  const workspaceName = company?.company_name || company?.name || "there";
  const now = new Date();
  const yesterdayKey = dateInputValue(new Date(now.getTime() - 86400000));
  const yesterdayBookings = bookings.filter((booking) => dateInputValue(new Date(booking.starts_at)) === yesterdayKey).length;
  const previousWeekStart = new Date(now.getTime() - 14 * 86400000);
  const previousWeekEnd = new Date(now.getTime() - 7 * 86400000);
  const previousWeekBookings = bookings.filter((booking) => { const starts = new Date(booking.starts_at); return starts >= previousWeekStart && starts < previousWeekEnd; });
  const previousCompleted = previousWeekBookings.filter((booking) => booking.status === "completed").length;
  const previousRevenue = previousWeekBookings.reduce((sum, booking) => sum + Number(booking.total_amount || 0), 0);
  const activity = bookings.slice(0, 5);
  const densityDays = Array.from({ length: 7 }, (_, index) => {
    const date = new Date(); date.setDate(date.getDate() - 3 + index);
    const key = dateInputValue(date);
    return { label: date.toLocaleDateString("en-GB", { weekday: "short" }).slice(0, 2), value: bookings.filter((booking) => dateInputValue(new Date(booking.starts_at)) === key).length, today: key === todayKey };
  });

  return <>
    <section className="standard-dashboard-hero">
      <div className="standard-dashboard-hero-copy"><p className="standard-dashboard-kicker">Booking overview</p><h1>Welcome, {workspaceName}</h1><p>Here’s what’s happening with your bookings today.</p></div>
      <Link className="standard-dashboard-hero-action" href="/bookings/new"><Plus size={17} /> New booking</Link>
    </section>
    <div className="kpi-grid">
      <StatCard label="Total bookings" value={bookings.length || 0} delta={periodDelta(bookings.length, previousWeekBookings.length)} trend={bookings.length >= previousWeekBookings.length ? "up" : "down"} icon={<CalendarDays size={18} />} />
      <StatCard label="Today’s bookings" value={todayBookings.length} delta={periodDelta(todayBookings.length, yesterdayBookings)} trend={todayBookings.length >= yesterdayBookings ? "up" : "down"} icon={<Clock3 size={18} />} />
      <StatCard label="Upcoming" value={upcoming.length} delta={periodDelta(upcoming.length, previousWeekBookings.filter((booking) => new Date(booking.starts_at) >= now).length)} trend="up" icon={<CalendarClock size={18} />} />
      <StatCard label="Completed" value={completed.length} delta={periodDelta(completed.length, previousCompleted)} trend={completed.length >= previousCompleted ? "up" : "down"} icon={<CheckCircle2 size={18} />} />
      <StatCard label="Revenue" value={money(revenue || 0, currency)} delta={periodDelta(revenue, previousRevenue)} trend={revenue >= previousRevenue ? "up" : "down"} icon={<CreditCard size={18} />} tone="blue" />
    </div>
    <div className="dashboard-main-grid">
      <section className="section-card upcoming-card">
        <SectionHeader title="Upcoming bookings" subtitle="Your next reservations at a glance" action={<Link href="/bookings">View all <ArrowRight size={15} /></Link>} />
        <div className="booking-table desktop-table"><div className="booking-table-head"><span>Booking</span><span>Customer</span><span>Schedule</span><span>Status</span><span>Total</span><span /></div>{loading ? <SkeletonRows /> : upcoming.length ? upcoming.map((booking) => <BookingRow key={booking.id} booking={booking} />) : <EmptyState compact icon={<CalendarDays size={20} />} title="No upcoming bookings" description="Your next reservations will appear here." action={<Link href="/bookings/new" className="secondary-button">Create booking</Link>} />}</div>
        <div className="mobile-booking-list">{upcoming.map((booking) => <BookingCard key={booking.id} booking={booking} />)}</div>
      </section>
      <section className="section-card calendar-widget-card">
        <SectionHeader title="Booking calendar" subtitle="Reservation density" action={<Link href="/calendar"><MoreHorizontal size={17} /></Link>} />
        <div className="mini-calendar-head"><button className="icon-button"><ChevronLeft size={16} /></button><strong>August 2026</strong><button className="icon-button"><ChevronRight size={16} /></button></div>
        <div className="density-chart">{densityDays.map((day) => <div key={day.label} className="density-column"><span className="density-value">{day.value}</span><div className={`density-bar level-${Math.min(day.value, 4)} ${day.today ? "today" : ""}`} /><small>{day.label}</small></div>)}</div>
        <div className="calendar-legend"><span><i className="legend-dot busy" />Booked</span><span><i className="legend-dot open" />Open slots</span></div>
      </section>
    </div>
    <div className="dashboard-secondary-grid">
      <section className="section-card schedule-card">
        <SectionHeader title="Today’s schedule" subtitle={todayBookings.length ? `${todayBookings.length} reservations scheduled` : "Your day at a glance"} action={<Link href="/calendar">Open calendar <ArrowRight size={15} /></Link>} />
        {todayBookings.length ? <div className="schedule-timeline">{todayBookings.slice(0, 6).map((booking) => <ScheduleItem key={booking.id} booking={booking} />)}</div> : <EmptyState icon={<Clock3 size={22} />} title="Your schedule is clear" description="Create a booking to start planning the day." action={<Link href="/bookings/new" className="secondary-button">New booking</Link>} />}
      </section>
      <section className="section-card activity-card">
        <SectionHeader title="Recent activity" subtitle="Latest changes across your workspace" action={<Link href="/notifications"><MoreHorizontal size={17} /></Link>} />
        <div className="activity-list">{activity.length ? activity.map((booking) => <div className="activity-item" key={booking.id}><span className={`activity-icon ${booking.status}`}><ActivityIcon status={booking.status} /></span><div><strong>{booking.status === "completed" ? "Booking completed" : booking.status === "cancelled" ? "Booking cancelled" : "Booking created"}</strong><span>{booking.service?.name || "Reservation"} · {booking.customer?.name || booking.guest_name || "Guest customer"}</span></div><time>{timeLabel(booking.updated_at)}</time></div>) : <EmptyState compact icon={<Sparkles size={20} />} title="No activity yet" description="Updates will appear as your team works." />}</div>
      </section>
    </div>
    <section className="quick-actions-row"><div><span className="eyebrow">Move faster</span><h2>Everything your team needs to stay in sync.</h2></div><div className="quick-actions"><QuickAction href="/bookings/new" icon={<Plus size={17} />} label="New booking" /><QuickAction href="/customers" icon={<UserRound size={17} />} label="Add customer" /><QuickAction href="/services" icon={<Sparkles size={17} />} label="Add service" /><QuickAction href="/calendar" icon={<CalendarDays size={17} />} label="Open calendar" /></div></section>
  </>;
}

export function BookingsView() {
  const { bookings } = useBookingData();
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState<BookingStatus | "all">("all");
  const filtered = bookings.filter((booking) => {
    const query = search.toLowerCase().trim();
    const matchesQuery = !query || [booking.booking_number, booking.customer?.name, booking.guest_name, booking.service?.name, booking.resource?.name].some((value) => value?.toLowerCase().includes(query));
    return matchesQuery && (status === "all" || booking.status === status);
  });
  return <>
    <PageHeader eyebrow="Operations" title="Bookings" description="Keep every reservation, customer, and payment in one place." action={<Link className="primary-button" href="/bookings/new"><Plus size={17} /> New booking</Link>} />
    <section className="section-card list-page-card">
      <div className="list-toolbar"><div className="search-field"><Search size={17} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search booking, customer, service…" aria-label="Search bookings" /></div><div className="toolbar-filters"><select value={status} onChange={(event) => setStatus(event.target.value as BookingStatus | "all")} aria-label="Filter by booking status"><option value="all">All statuses</option>{["pending", "confirmed", "checked_in", "in_progress", "completed", "cancelled", "no_show"].map((item) => <option key={item} value={item}>{bookingStatusLabel(item as BookingStatus)}</option>)}</select><button className="secondary-button filter-button"><Filter size={16} /> Filters</button></div></div>
      <div className="booking-table desktop-table"><div className="booking-table-head"><span>Booking</span><span>Customer</span><span>Schedule</span><span>Status</span><span>Payment</span><span>Total</span></div>{filtered.length ? filtered.map((booking) => <BookingRow key={booking.id} booking={booking} showPayment />) : <EmptyState icon={<Search size={22} />} title="No bookings match these filters" description="Try a different search or create a new booking." action={<Link href="/bookings/new" className="secondary-button">New booking</Link>} />}</div>
      <div className="mobile-booking-list">{filtered.map((booking) => <BookingCard key={booking.id} booking={booking} showPayment />)}</div>
      <div className="table-footer"><span>Showing {filtered.length} of {bookings.length} bookings</span><span className="pagination"><button className="icon-button" disabled><ChevronLeft size={16} /></button><strong>1</strong><button className="icon-button" disabled><ChevronRight size={16} /></button></span></div>
    </section>
  </>;
}

export function NewBookingView() {
  const router = useRouter();
  const { companyId, services, customers, locations, resources, staff, addBooking, demo } = useBookingData();
  const [step, setStep] = useState(1);
  const [serviceId, setServiceId] = useState(services[0]?.id || "");
  const [customerId, setCustomerId] = useState("");
  const [guestName, setGuestName] = useState("");
  const [guestEmail, setGuestEmail] = useState("");
  const [locationId, setLocationId] = useState(locations[0]?.id || "");
  const [resourceId, setResourceId] = useState("");
  const [staffId, setStaffId] = useState("");
  const [date, setDate] = useState(dateInputValue());
  const [time, setTime] = useState("09:00");
  const [slots, setSlots] = useState<{ startsAt: string; endsAt: string; available: boolean }[]>([]);
  const [notes, setNotes] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const selectedService = services.find((service) => service.id === serviceId);
  const selectedCustomer = customers.find((customer) => customer.id === customerId);
  const total = calculateBookingTotals({ unitPrice: selectedService?.price || 0, quantity: 1, taxRate: selectedService?.tax_rate || 0, depositType: selectedService?.deposit_type, depositValue: selectedService?.deposit_value });

  useEffect(() => {
    if (demo) { setSlots(["09:00", "09:30", "10:00", "11:00", "13:30", "15:00"].map((value) => ({ startsAt: localIso(date, value), endsAt: localIso(date, value), available: true }))); return; }
    const client = createClient();
    if (!client || !companyId || !serviceId || !date) return;
    void getAvailableSlots(client, { companyId, serviceId, date, locationId: locationId || null, resourceId: resourceId || null, staffId: staffId || null }).then(setSlots).catch(() => setSlots([]));
  }, [companyId, date, demo, locationId, resourceId, serviceId, staffId]);

  function next() { setError(""); if (step === 1 && !serviceId) { setError("Choose a service to continue."); return; } if (step === 2 && !customerId && !guestName.trim()) { setError("Choose a customer or enter a guest name."); return; } if (step === 3 && !time) { setError("Choose an available time."); return; } setStep((current) => Math.min(4, current + 1)); }
  async function submit(event?: FormEvent) {
    event?.preventDefault();
    if (!companyId || !serviceId) return;
    setSubmitting(true); setError("");
    try {
      const created = await addBooking({ companyId, customerId: customerId || null, guestName: customerId ? null : guestName, guestEmail: customerId ? null : guestEmail || null, serviceId, locationId: locationId || null, resourceId: resourceId || null, staffId: staffId || null, startsAt: localIso(date, time), endsAt: localIsoAfter(date, time, selectedService?.duration_minutes || 60), participantCount: 1, quantity: 1, status: "confirmed", notes, source: "admin" });
      router.push(`/bookings/${created.id}`);
    } catch (submitError) { setError(submitError instanceof Error ? submitError.message : "The booking could not be created."); }
    finally { setSubmitting(false); }
  }

  return <>
    <PageHeader eyebrow="New reservation" title="Create a booking" description="A fast, server-validated flow for your front desk." action={<Link className="secondary-button" href="/bookings"><ArrowLeft size={16} /> Back to bookings</Link>} />
    <div className="booking-flow-layout"><section className="section-card booking-flow-card"><div className="flow-progress">{["Service", "Customer", "Time", "Review"].map((label, index) => <div className={`flow-step ${step > index + 1 ? "done" : ""} ${step === index + 1 ? "current" : ""}`} key={label}><span>{step > index + 1 ? <Check size={14} /> : index + 1}</span><strong>{label}</strong></div>)}</div>
      <form onSubmit={submit}>
        {step === 1 && <FlowStep title="What would they like to book?" description="Choose a service. Availability and price will be calculated from the organization rules."><div className="choice-grid service-choice-grid">{services.map((service) => <button type="button" className={`choice-card ${service.id === serviceId ? "selected" : ""}`} key={service.id} onClick={() => setServiceId(service.id)}><span className="choice-icon"><Sparkles size={18} /></span><span><strong>{service.name}</strong><small>{service.duration_minutes >= 120 ? `${Math.round(service.duration_minutes / 60)} hours` : `${service.duration_minutes} min`} · {money(service.price, service.currency)}</small></span>{service.id === serviceId && <CheckCircle2 size={18} className="choice-check" />}</button>)}</div>{!services.length && <EmptyState icon={<Sparkles size={22} />} title="Create a service first" description="Services define duration, price, buffers, and capacity." action={<Link href="/services" className="secondary-button">Open services</Link>} />}</FlowStep>}
        {step === 2 && <FlowStep title="Who is this booking for?" description="Use an existing customer or create a guest reservation with contact details."><div className="form-grid"><label className="field-label full">Existing customer<select value={customerId} onChange={(event) => { setCustomerId(event.target.value); if (event.target.value) setGuestName(""); }}><option value="">Guest customer</option>{customers.map((customer) => <option key={customer.id} value={customer.id}>{customer.name} · {customer.email || customer.phone || "No contact"}</option>)}</select></label>{!customerId && <><label className="field-label">Guest name<input value={guestName} onChange={(event) => setGuestName(event.target.value)} placeholder="Customer name" /></label><label className="field-label">Email <span className="optional">optional</span><input type="email" value={guestEmail} onChange={(event) => setGuestEmail(event.target.value)} placeholder="customer@email.com" /></label></>}</div>{selectedCustomer && <div className="selected-customer"><span className="customer-avatar">{initials(selectedCustomer.name)}</span><div><strong>{selectedCustomer.name}</strong><span>{selectedCustomer.email || selectedCustomer.phone || "No contact details"}</span></div><CheckCircle2 size={18} /></div>}</FlowStep>}
        {step === 3 && <FlowStep title="Choose a time" description="The server checks staff, resource, buffers, working hours, and conflicts before confirmation."><div className="form-grid"><label className="field-label">Date<input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label><label className="field-label">Location<select value={locationId} onChange={(event) => setLocationId(event.target.value)}><option value="">Any location</option>{locations.map((location) => <option key={location.id} value={location.id}>{location.name}</option>)}</select></label><label className="field-label">Provider <span className="optional">optional</span><select value={staffId} onChange={(event) => setStaffId(event.target.value)}><option value="">Any provider</option>{staff.map((member) => <option key={member.id} value={member.id}>{member.display_name}</option>)}</select></label><label className="field-label">Resource <span className="optional">optional</span><select value={resourceId} onChange={(event) => setResourceId(event.target.value)}><option value="">Any resource</option>{resources.filter((resource) => !locationId || resource.location_id === locationId).map((resource) => <option key={resource.id} value={resource.id}>{resource.name}</option>)}</select></label></div><div className="slot-picker"><span className="slot-picker-label">Available times for {dayLabel(`${date}T12:00:00`)}</span><div className="slot-grid">{slots.filter((slot) => slot.available).map((slot) => { const value = timeLabel(slot.startsAt); return <button type="button" key={slot.startsAt} className={`time-slot ${value === time ? "selected" : ""}`} onClick={() => setTime(value)}>{value}</button>; })}</div>{!slots.filter((slot) => slot.available).length && <p className="inline-empty">No slots are open for this combination. Change the date or provider.</p>}</div></FlowStep>}
        {step === 4 && <FlowStep title="Review and confirm" description="The server will re-check the slot and calculate the final total when you confirm."><div className="review-card"><div><span>Service</span><strong>{selectedService?.name || "—"}</strong></div><div><span>Customer</span><strong>{selectedCustomer?.name || guestName || "Guest customer"}</strong></div><div><span>Schedule</span><strong>{dateLabel(localIso(date, time))} · {time}</strong></div><div><span>Location</span><strong>{locations.find((location) => location.id === locationId)?.name || "Any location"}</strong></div><div><span>Total</span><strong>{money(total.total, selectedService?.currency)}</strong></div><div><span>Deposit</span><strong>{total.deposit ? money(total.deposit, selectedService?.currency) : "Not required"}</strong></div></div><label className="field-label full">Notes <span className="optional">optional</span><textarea value={notes} onChange={(event) => setNotes(event.target.value)} rows={3} placeholder="Add customer or internal context…" /></label></FlowStep>}
        {error && <p className="form-error flow-error" role="alert">{error}</p>}
        <div className="flow-actions">{step > 1 ? <button type="button" className="secondary-button" onClick={() => setStep((current) => current - 1)}><ChevronLeft size={16} /> Back</button> : <span />}{step < 4 ? <button type="button" className="primary-button" onClick={next}>Continue <ArrowRight size={16} /></button> : <button type="submit" className="primary-button" disabled={submitting}>{submitting ? "Confirming…" : "Confirm booking"}<Check size={16} /></button>}</div>
      </form>
    </section><aside className="booking-flow-summary"><div className="summary-accent" /><span className="eyebrow">Booking summary</span><h2>{selectedService?.name || "Select a service"}</h2><p>{selectedService?.description || "Start by selecting a service and we’ll keep the rest of the flow simple."}</p><div className="summary-list"><SummaryLine icon={<Clock3 size={16} />} label="Duration" value={selectedService ? `${selectedService.duration_minutes} min` : "—"} /><SummaryLine icon={<CalendarDays size={16} />} label="Schedule" value={time ? `${date} · ${time}` : "Choose a time"} /><SummaryLine icon={<MapPin size={16} />} label="Location" value={locations.find((location) => location.id === locationId)?.name || "Any location"} /></div><div className="summary-total"><span>Estimated total</span><strong>{money(total.total, selectedService?.currency)}</strong><small>Prices are calculated server-side at confirmation.</small></div></aside></div>
  </>;
}

export function BookingDetailView({ id }: { id: string }) {
  const router = useRouter();
  const { bookings, changeStatus, demo } = useBookingData();
  const booking = bookings.find((item) => item.id === id);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  if (!booking) return <><PageHeader eyebrow="Booking" title="Booking not found" description="This reservation may have been removed or belongs to another workspace." action={<Link className="secondary-button" href="/bookings"><ArrowLeft size={16} /> Back to bookings</Link>} /><EmptyState icon={<Search size={22} />} title="We couldn’t find that booking" description="Check the reference or return to the booking list." /></>;
  const bookingId = booking.id;
  async function action(status: string) { setBusy(true); setMessage(""); try { await changeStatus(bookingId, status); setMessage(`Booking marked ${bookingStatusLabel(status as BookingStatus).toLowerCase()}.`); } catch (error) { setMessage(error instanceof Error ? error.message : "That action could not be completed."); } finally { setBusy(false); } }
  const customerName = booking.customer?.name || booking.guest_name || "Guest customer";
  const canConfirm = ["draft", "pending", "rescheduled"].includes(booking.status);
  const canCheckIn = booking.status === "confirmed";
  const canStart = booking.status === "checked_in";
  const canComplete = booking.status === "in_progress";
  return <>
    <PageHeader eyebrow={booking.booking_number} title={booking.service?.name || "Booking details"} description={`${dateLabel(booking.starts_at)} · ${timeLabel(booking.starts_at)} – ${timeLabel(booking.ends_at)}`} action={<div className="page-actions"><Link className="secondary-button" href="/bookings"><ArrowLeft size={16} /> Back</Link>{canConfirm && <button className="primary-button" disabled={busy} onClick={() => void action("confirmed")}><Check size={16} /> Confirm</button>}{canCheckIn && <button className="primary-button" disabled={busy} onClick={() => void action("checked_in")}>Check in</button>}{canStart && <button className="primary-button" disabled={busy} onClick={() => void action("in_progress")}>Start service</button>}{canComplete && <button className="primary-button" disabled={busy} onClick={() => void action("completed")}>Complete</button>} {!demo && !["cancelled", "completed", "no_show"].includes(booking.status) && <button className="danger-button" disabled={busy} onClick={() => void action("cancelled")}>Cancel</button>}</div>} />
    {message && <div className={`inline-notice ${message.includes("could") || message.includes("permission") ? "error" : "success"}`}><ShieldCheck size={16} />{message}</div>}
    <div className="detail-grid"><section className="section-card detail-overview-card"><div className="detail-status-row"><StatusBadge status={booking.status} /><span className="detail-reference">Created {dateLabel(booking.created_at)}</span></div><div className="detail-hero"><span className="detail-service-icon"><Sparkles size={23} /></span><div><span className="eyebrow">{booking.booking_number}</span><h2>{booking.service?.name || "Reservation"}</h2><p>{booking.location?.name || "Location to be confirmed"}{booking.staff?.display_name ? ` · ${booking.staff.display_name}` : ""}</p></div></div><div className="detail-info-grid"><InfoBlock icon={<UserRound size={17} />} label="Customer" value={customerName} subvalue={booking.customer?.email || booking.guest_email || booking.customer?.phone || booking.guest_phone || "No contact details"} /><InfoBlock icon={<CalendarDays size={17} />} label="Schedule" value={dateLabel(booking.starts_at)} subvalue={`${timeLabel(booking.starts_at)} – ${timeLabel(booking.ends_at)} · ${booking.timezone}`} /><InfoBlock icon={<MapPin size={17} />} label="Location" value={booking.location?.name || "Any location"} subvalue={booking.location?.timezone || booking.timezone} /><InfoBlock icon={<Users size={17} />} label="Assigned team" value={booking.staff?.display_name || "Unassigned"} subvalue={booking.resource?.name || "No resource assigned"} /></div><div className="detail-section"><div className="detail-section-heading"><h3>Notes</h3><button className="icon-button"><MoreHorizontal size={17} /></button></div><p className="detail-note">{booking.notes || "No customer notes have been added."}</p></div><div className="detail-section"><div className="detail-section-heading"><h3>Activity</h3><span className="muted-text">Audit history</span></div><div className="detail-activity"><div><span className="activity-line-dot blue" /><p><strong>Booking created</strong><span>Reservation entered by your team</span></p><time>{timeLabel(booking.created_at)}</time></div><div><span className="activity-line-dot green" /><p><strong>Status is {bookingStatusLabel(booking.status).toLowerCase()}</strong><span>All changes remain visible in the audit log</span></p><time>{timeLabel(booking.updated_at)}</time></div></div></div></section><aside className="detail-side"><section className="section-card payment-summary-card"><SectionHeader title="Payment" subtitle="Booking balance" action={<Link href="/payments"><MoreHorizontal size={17} /></Link>} /><div className="payment-total"><span>Total</span><strong>{money(booking.total_amount, booking.currency)}</strong></div><div className="payment-rows"><div><span>Paid</span><strong>{money(booking.paid_amount, booking.currency)}</strong></div><div><span>Balance</span><strong>{money(Math.max(0, booking.total_amount - booking.paid_amount), booking.currency)}</strong></div><div><span>Status</span><StatusBadge status={booking.payment_status} payment /></div></div><button className="secondary-button full-button"><CreditCard size={16} /> Collect payment</button><button className="text-button full-button"><FileText size={16} /> Create invoice</button></section><section className="section-card policy-card"><span className="eyebrow">Booking policy</span><h3>Changes stay traceable</h3><p>Reschedules, cancellations, payment updates, and staff actions are recorded for this organization.</p><Link href="/settings">Review settings <ArrowRight size={15} /></Link></section></aside></div>
  </>;
}

export function CalendarView() {
  const { bookings } = useBookingData();
  const [date, setDate] = useState(dateInputValue());
  const [view, setView] = useState<"day" | "week" | "agenda">("day");
  const selected = bookings.filter((booking) => dateInputValue(new Date(booking.starts_at)) === date && booking.status !== "cancelled").sort((a, b) => a.starts_at.localeCompare(b.starts_at));
  const week = Array.from({ length: 7 }, (_, index) => { const base = new Date(`${date}T12:00:00`); base.setDate(base.getDate() - base.getDay() + 1 + index); return base; });
  return <><PageHeader eyebrow="Schedule" title="Calendar" description="See today’s flow and move confidently through the week." action={<Link className="primary-button" href="/bookings/new"><Plus size={17} /> New booking</Link>} /><section className="section-card calendar-page-card"><div className="calendar-toolbar"><div className="calendar-view-tabs">{(["day", "week", "agenda"] as const).map((item) => <button key={item} className={view === item ? "active" : ""} onClick={() => setView(item)}>{item[0].toUpperCase() + item.slice(1)}</button>)}</div><div className="calendar-date-controls"><button className="icon-button" onClick={() => { const next = new Date(`${date}T12:00:00`); next.setDate(next.getDate() - 1); setDate(dateInputValue(next)); }}><ChevronLeft size={17} /></button><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /><button className="icon-button" onClick={() => { const next = new Date(`${date}T12:00:00`); next.setDate(next.getDate() + 1); setDate(dateInputValue(next)); }}><ChevronRight size={17} /></button><button className="secondary-button today-button" onClick={() => setDate(dateInputValue())}>Today</button></div></div>{view === "week" ? <div className="week-calendar">{week.map((day) => { const key = dateInputValue(day); const dayBookings = bookings.filter((booking) => dateInputValue(new Date(booking.starts_at)) === key && booking.status !== "cancelled"); return <div className={`week-day ${key === date ? "selected" : ""}`} key={key} onClick={() => { setDate(key); setView("day"); }}><div className="week-day-head"><span>{day.toLocaleDateString("en-GB", { weekday: "short" })}</span><strong>{day.getDate()}</strong></div><div className="week-day-events">{dayBookings.slice(0, 4).map((booking) => <span key={booking.id} className={`week-event ${bookingStatusTone(booking.status)}`}>{timeLabel(booking.starts_at)} {booking.service?.name}</span>)}{!dayBookings.length && <small>Open day</small>}</div></div>; })}</div> : <div className="day-calendar"><div className="day-calendar-heading"><div><span className="eyebrow">{view === "agenda" ? "Upcoming agenda" : "Day view"}</span><h2>{dayLabel(`${date}T12:00:00`)}</h2></div><span className="calendar-count">{selected.length} bookings</span></div>{view === "agenda" ? <div className="agenda-list">{bookings.filter((booking) => new Date(booking.starts_at) >= new Date()).slice(0, 20).map((booking) => <ScheduleItem key={booking.id} booking={booking} />)}</div> : <div className="day-timeline">{Array.from({ length: 10 }, (_, index) => 8 + index).map((hour) => { const hourBookings = selected.filter((booking) => new Date(booking.starts_at).getHours() === hour); return <div className="hour-row" key={hour}><span>{String(hour).padStart(2, "0")}:00</span><div>{hourBookings.map((booking) => <Link key={booking.id} href={`/bookings/${booking.id}`} className={`calendar-event ${bookingStatusTone(booking.status)}`}><strong>{booking.service?.name || "Booking"}</strong><span>{timeLabel(booking.starts_at)} · {booking.customer?.name || booking.guest_name}</span></Link>)}</div></div>; })}</div>}</div>}</section></>;
}

type DirectoryKind = "customers" | "services" | "resources" | "staff" | "payments" | "notifications" | "reports" | "settings";
export function DirectoryView({ kind }: { kind: DirectoryKind }) {
  const data = useBookingData();
  const [search, setSearch] = useState("");
  const [modal, setModal] = useState(false);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [formError, setFormError] = useState("");
  async function save(event: FormEvent) { event.preventDefault(); setFormError(""); if (!name.trim()) { setFormError("A name is required."); return; } const client = createClient(); if (data.demo) { setModal(false); setName(""); return; } if (!client || !data.companyId || !data.user?.id) { setFormError("The workspace session is not ready."); return; } try { if (kind === "customers") await createCustomer(client, { companyId: data.companyId, userId: data.user.id, name, email: email || null }); else if (kind === "services") await createService(client, { companyId: data.companyId, name, description: null, durationMinutes: 60, price: 0, currency: "EUR" }); await data.refresh(); setModal(false); setName(""); setEmail(""); } catch (error) { setFormError(error instanceof Error ? error.message : "Could not save this record."); } }
  if (["payments", "notifications", "reports", "settings"].includes(kind)) return <UtilityViewNew kind={kind as "payments" | "notifications" | "reports" | "settings"} />;
  const directoryKind = kind as "customers" | "services" | "resources" | "staff";
  const config = directoryConfig[directoryKind];
  const rows: any[] = directoryKind === "customers" ? data.customers.filter((row) => row.name.toLowerCase().includes(search.toLowerCase()) || row.email?.toLowerCase().includes(search.toLowerCase())) : directoryKind === "services" ? data.services.filter((row) => row.name.toLowerCase().includes(search.toLowerCase())) : directoryKind === "resources" ? data.resources.filter((row) => row.name.toLowerCase().includes(search.toLowerCase())) : data.staff.filter((row) => row.display_name.toLowerCase().includes(search.toLowerCase()));
  return <><PageHeader eyebrow={config.eyebrow} title={config.title} description={config.description} action={<button className="primary-button" onClick={() => setModal(true)}><Plus size={17} /> {config.action}</button>} /><section className="section-card list-page-card"><div className="list-toolbar"><div className="search-field"><Search size={17} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={`Search ${directoryKind}…`} aria-label={`Search ${directoryKind}`} /></div><button className="secondary-button filter-button"><Filter size={16} /> Filters</button></div>{rows.length ? <div className="directory-grid">{rows.map((row) => <DirectoryCard key={row.id} kind={directoryKind} row={row} />)}</div> : <EmptyState icon={config.icon} title={config.emptyTitle} description={config.emptyDescription} action={<button className="secondary-button" onClick={() => setModal(true)}><Plus size={16} /> {config.action}</button>} />}</section>{modal && <div className="modal-backdrop" onMouseDown={() => setModal(false)}><div className="modal-card" onMouseDown={(event) => event.stopPropagation()}><div className="modal-heading"><div><span className="eyebrow">{config.eyebrow}</span><h2>{config.action}</h2></div><button className="icon-button" onClick={() => setModal(false)}><X size={18} /></button></div><form onSubmit={save}><label className="field-label">Name<input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder={directoryKind === "customers" ? "Customer name" : config.action} /></label>{directoryKind === "customers" && <label className="field-label">Email <span className="optional">optional</span><input type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="customer@email.com" /></label>}{formError && <p className="form-error" role="alert">{formError}</p>}<div className="modal-actions"><button type="button" className="secondary-button" onClick={() => setModal(false)}>Cancel</button><button className="primary-button" type="submit">Save {config.eyebrow.toLowerCase()}</button></div></form></div></div>}</>;
}

function UtilityView({ kind }: { kind: "payments" | "notifications" | "reports" | "settings" }) {
  const { bookings, services, locations, staff, resources } = useBookingData();
  if (kind === "settings") return <><PageHeader eyebrow="Workspace" title="Booking settings" description="Configure the rules that power every availability and customer experience." action={<button className="primary-button"><Check size={16} /> Save changes</button>} /><div className="settings-layout"><aside className="settings-tabs">{["General", "Locations", "Working hours", "Booking rules", "Cancellation policy", "Payments", "Notifications", "Public booking", "Localization", "Integrations", "Permissions"].map((item, index) => <button className={index === 0 ? "active" : ""} key={item}>{item}<ChevronRight size={15} /></button>)}</aside><section className="section-card settings-panel"><span className="eyebrow">General</span><h2>Make Booking work your way.</h2><p>These organization-level defaults are shared by the web and mobile clients.</p><div className="form-grid settings-fields"><label className="field-label">Timezone<select defaultValue="Europe/Belgrade"><option>Europe/Belgrade</option><option>UTC</option><option>Europe/Berlin</option></select></label><label className="field-label">Currency<select defaultValue="EUR"><option>EUR</option><option>USD</option><option>GBP</option></select></label><label className="field-label"><span>Minimum notice</span><select defaultValue="30 minutes"><option>0 minutes</option><option>30 minutes</option><option>2 hours</option><option>24 hours</option></select></label><label className="field-label"><span>Maximum booking window</span><select defaultValue="365 days"><option>30 days</option><option>90 days</option><option>365 days</option></select></label></div><div className="settings-toggle-row"><div><strong>Auto-confirm bookings</strong><span>Confirm new bookings immediately when availability passes.</span></div><button className="toggle on" aria-label="Auto-confirm bookings enabled"><i /></button></div><div className="settings-toggle-row"><div><strong>Require customer email</strong><span>Ask for an email when a guest customer is used.</span></div><button className="toggle" aria-label="Require customer email disabled"><i /></button></div></section></div></>;
  const title = kind === "payments" ? "Payments" : kind === "notifications" ? "Notifications" : "Reports";
  const description = kind === "payments" ? "Track booking balances and payment reconciliation." : kind === "notifications" ? "Keep your team and customers informed without duplicate sends." : "Understand demand, utilization, and customer retention.";
  return <><PageHeader eyebrow={kind === "reports" ? "Insights" : "Operations"} title={title} description={description} action={kind === "reports" ? <button className="secondary-button"><Download size={16} /> Export report</button> : <button className="secondary-button"><Settings2 size={16} /> Configure</button>} /><div className="utility-kpi-grid"><StatCard label="Total bookings" value={bookings.length} delta="12.5%" trend="up" icon={<CalendarDays size={18} />} /><StatCard label="Collected" value={money(bookings.reduce((sum, booking) => sum + booking.paid_amount, 0))} delta="9.4%" trend="up" icon={<CreditCard size={18} />} tone="blue" /><StatCard label="Open balance" value={money(bookings.reduce((sum, booking) => sum + Math.max(0, booking.total_amount - booking.paid_amount), 0))} delta="2.1%" trend="down" icon={<FileText size={18} />} /><StatCard label="Utilization" value={`${Math.min(100, Math.round((bookings.length / Math.max(services.length * 5, 1)) * 100))}%`} delta="6.8%" trend="up" icon={<Sparkles size={18} />} /></div><div className="dashboard-secondary-grid"><section className="section-card"><SectionHeader title={kind === "notifications" ? "Delivery activity" : kind === "reports" ? "Booking performance" : "Recent transactions"} subtitle="Shared across your OperiX workspace" action={<MoreHorizontal size={17} />} />{kind === "notifications" ? <div className="notification-settings-list"><NotificationRow title="Booking confirmation" channels="Email · In-app" state="Active" /><NotificationRow title="24-hour reminder" channels="Push · Email" state="Active" /><NotificationRow title="Payment received" channels="In-app" state="Active" /><NotificationRow title="Waitlist slot available" channels="Email" state="Paused" /></div> : <div className="report-bars">{["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((day, index) => <div key={day}><span>{day}</span><div><i style={{ height: `${28 + (index * 11) % 54}%` }} /></div><strong>{3 + index * 2}</strong></div>)}</div>}</section><section className="section-card insight-card"><span className="eyebrow">Connected data</span><h2>One source of truth.</h2><p>Bookings, services, staff, resources, and payments are scoped to your active organization and stay synchronized across clients.</p><div className="connected-list"><span><CheckCircle2 size={16} /> {locations.length} locations</span><span><CheckCircle2 size={16} /> {staff.length} providers</span><span><CheckCircle2 size={16} /> {resources.length} resources</span></div></section></div></>;
}

function UtilityViewNew({ kind }: { kind: "payments" | "notifications" | "reports" | "settings" }) {
  const data = useBookingData();
  if (kind === "settings") return <SettingsUtility />;
  if (kind === "payments") {
    const paid = data.bookings.reduce((sum, booking) => sum + Number(booking.paid_amount || 0), 0);
    const balance = data.bookings.reduce((sum, booking) => sum + Math.max(0, Number(booking.total_amount || 0) - Number(booking.paid_amount || 0)), 0);
    return <><PageHeader eyebrow="Finance" title="Payments" description="Track booking balances against the shared OperiX payment records." /><div className="utility-kpi-grid"><StatCard label="Collected" value={money(paid)} delta={String(data.payments.length) + " records"} trend="up" icon={<CreditCard size={18} />} tone="blue" /><StatCard label="Open balance" value={money(balance)} delta={String(data.bookings.filter((booking) => booking.paid_amount < booking.total_amount).length) + " bookings"} trend="down" icon={<FileText size={18} />} /><StatCard label="Paid bookings" value={data.bookings.filter((booking) => booking.payment_status === "paid").length} delta="Live" trend="up" icon={<CheckCircle2 size={18} />} /><StatCard label="Failed" value={data.bookings.filter((booking) => booking.payment_status === "failed").length} delta="Live" trend="down" icon={<X size={18} />} /></div><section className="section-card list-page-card"><SectionHeader title="Booking payment status" subtitle="Amounts are read from the shared Booking ledger." />{data.bookings.length ? <div className="booking-table desktop-table"><div className="booking-table-head"><span>Booking</span><span>Customer</span><span>Schedule</span><span>Status</span><span>Payment</span><span>Total</span></div>{data.bookings.slice(0, 12).map((booking) => <BookingRow key={booking.id} booking={booking} showPayment />)}</div> : <EmptyState icon={<CreditCard size={22} />} title="No payment records yet" description="Payment state will appear here when a booking is created." />}</section></>;
  }
  if (kind === "notifications") {
    return <><PageHeader eyebrow="Operations" title="Notifications" description="Review delivery events generated by the shared booking notification pipeline." /><section className="section-card list-page-card"><SectionHeader title="Delivery activity" subtitle={String(data.notifications.length) + " logged events"} />{data.notifications.length ? <div className="notification-settings-list">{data.notifications.map((notification) => <div className="notification-row" key={notification.id}><span className="notification-row-icon"><BellIcon /></span><div><strong>{notification.event_type.replace(/\./g, " · ")}</strong><span>{notification.channel} · {notification.recipient || "Workspace recipient"}</span></div><span className={"state-pill " + (["sent", "delivered"].includes(notification.status) ? "active" : "")}>{notification.status}</span><ChevronRight size={15} /></div>)}</div> : <EmptyState icon={<Mail size={22} />} title="No delivery events yet" description="Booking confirmations, reminders, and payment notifications will be tracked here." />}</section></>;
  }
  const completed = data.bookings.filter((booking) => booking.status === "completed");
  const cancelled = data.bookings.filter((booking) => booking.status === "cancelled");
  const noShows = data.bookings.filter((booking) => booking.status === "no_show");
  const serviceCounts = data.services.map((service) => ({ name: service.name, count: data.bookings.filter((booking) => booking.service_id === service.id).length })).sort((a, b) => b.count - a.count).slice(0, 7);
  const maxCount = Math.max(...serviceCounts.map((entry) => entry.count), 1);
  const averageValue = data.bookings.length ? data.bookings.reduce((sum, booking) => sum + Number(booking.total_amount || 0), 0) / data.bookings.length : 0;
  return <><PageHeader eyebrow="Insights" title="Reports" description="Operational metrics calculated from the booking records in your active organization." action={<button className="secondary-button" onClick={() => window.print()}><Download size={16} /> Export / print</button>} /><div className="utility-kpi-grid"><StatCard label="Total bookings" value={data.bookings.length} delta="Live" trend="up" icon={<CalendarDays size={18} />} /><StatCard label="Completed" value={completed.length} delta={String(data.bookings.length ? Math.round(completed.length / data.bookings.length * 100) : 0) + "% of total"} trend="up" icon={<CheckCircle2 size={18} />} tone="blue" /><StatCard label="Cancellations" value={cancelled.length} delta={String(data.bookings.length ? Math.round(cancelled.length / data.bookings.length * 100) : 0) + "% of total"} trend="down" icon={<X size={18} />} /><StatCard label="Average value" value={money(averageValue)} delta={String(noShows.length) + " no-shows"} trend="down" icon={<FileText size={18} />} /></div><div className="dashboard-secondary-grid"><section className="section-card"><SectionHeader title="Bookings by service" subtitle="Current loaded booking data" />{serviceCounts.length ? <div className="report-bars">{serviceCounts.map((entry) => <div key={entry.name}><span>{entry.name.slice(0, 10)}</span><div><i style={{ height: String(Math.max(8, entry.count / maxCount * 100)) + "%" }} /></div><strong>{entry.count}</strong></div>)}</div> : <EmptyState icon={<Sparkles size={22} />} title="No service activity yet" description="Create bookings to see service demand." />}</section><section className="section-card insight-card"><span className="eyebrow">Connected data</span><h2>One source of truth.</h2><p>Reports use the same tenant-scoped bookings, services, staff, resources, and payment state shown in the rest of Booking.</p><div className="connected-list"><span><CheckCircle2 size={16} /> {data.locations.length} locations</span><span><CheckCircle2 size={16} /> {data.staff.length} providers</span><span><CheckCircle2 size={16} /> {data.resources.length} resources</span></div></section></div></>;
}

function SettingsUtility() {
  const data = useBookingData();
  const [draft, setDraft] = useState({ timezone: data.settings?.timezone || "Europe/Belgrade", currency: data.settings?.currency || "EUR", minimum_booking_notice_minutes: String(data.settings?.minimum_booking_notice_minutes || 30), maximum_advance_booking_days: String(data.settings?.maximum_advance_booking_days || 365), auto_confirm: data.settings?.auto_confirm ?? true, require_customer_email: data.settings?.require_customer_email ?? false });
  const [saved, setSaved] = useState(false);
  async function save() {
    await data.saveSettings({ timezone: draft.timezone, currency: draft.currency, minimum_booking_notice_minutes: Number(draft.minimum_booking_notice_minutes), maximum_advance_booking_days: Number(draft.maximum_advance_booking_days), auto_confirm: draft.auto_confirm, require_customer_email: draft.require_customer_email });
    setSaved(true);
    window.setTimeout(() => setSaved(false), 1800);
  }
  return <><PageHeader eyebrow="Workspace" title="Booking settings" description="Configure the organization rules shared by the web and mobile clients." action={<button className="primary-button" onClick={() => void save()}><Check size={16} /> {saved ? "Saved" : "Save changes"}</button>} /><div className="settings-layout"><aside className="settings-tabs">{["General", "Locations", "Working hours", "Booking rules", "Cancellation policy", "Payments", "Notifications", "Public booking", "Localization", "Integrations", "Permissions"].map((item, index) => <button className={index === 0 ? "active" : ""} key={item} type="button">{item}<ChevronRight size={15} /></button>)}</aside><section className="section-card settings-panel"><span className="eyebrow">General</span><h2>Make Booking work your way.</h2><p>These values are persisted in the tenant-scoped booking_settings record.</p><div className="form-grid settings-fields"><label className="field-label">Timezone<select value={draft.timezone} onChange={(event) => setDraft((current) => ({ ...current, timezone: event.target.value }))}><option>Europe/Belgrade</option><option>UTC</option><option>Europe/Berlin</option></select></label><label className="field-label">Currency<select value={draft.currency} onChange={(event) => setDraft((current) => ({ ...current, currency: event.target.value }))}><option>EUR</option><option>USD</option><option>GBP</option></select></label><label className="field-label"><span>Minimum notice</span><select value={draft.minimum_booking_notice_minutes} onChange={(event) => setDraft((current) => ({ ...current, minimum_booking_notice_minutes: event.target.value }))}><option value="0">0 minutes</option><option value="30">30 minutes</option><option value="120">2 hours</option><option value="1440">24 hours</option></select></label><label className="field-label"><span>Maximum booking window</span><select value={draft.maximum_advance_booking_days} onChange={(event) => setDraft((current) => ({ ...current, maximum_advance_booking_days: event.target.value }))}><option value="30">30 days</option><option value="90">90 days</option><option value="365">365 days</option></select></label></div><ToggleRow title="Auto-confirm bookings" description="Confirm new bookings immediately when availability passes." value={draft.auto_confirm} onChange={() => setDraft((current) => ({ ...current, auto_confirm: !current.auto_confirm }))} /><ToggleRow title="Require customer email" description="Ask for an email when a guest customer is used." value={draft.require_customer_email} onChange={() => setDraft((current) => ({ ...current, require_customer_email: !current.require_customer_email }))} /></section></div></>;
}

function ToggleRow({ title, description, value, onChange }: { title: string; description: string; value: boolean; onChange: () => void }) {
  return <div className="settings-toggle-row"><div><strong>{title}</strong><span>{description}</span></div><button type="button" className={"toggle " + (value ? "on" : "")} aria-pressed={value} onClick={onChange} aria-label={title}><i /></button></div>;
}

function DirectoryCard({ kind, row }: { kind: "customers" | "services" | "resources" | "staff"; row: any }) {
  const title = kind === "staff" ? row.display_name : row.name;
  const subtitle = kind === "customers" ? row.email || row.phone || "No contact details" : kind === "services" ? `${row.duration_minutes} min · ${money(row.price, row.currency)}` : kind === "resources" ? `${row.resource_type} · Capacity ${row.capacity}` : row.role_title || "Booking provider";
  return <Link href={kind === "customers" ? "/bookings" : `/${kind}`} className="directory-card"><span className={`directory-icon ${kind}`}>{kind === "customers" ? <UserRound size={18} /> : kind === "services" ? <Sparkles size={18} /> : kind === "resources" ? <GridIcon /> : <Users size={18} />}</span><div><strong>{title}</strong><span>{subtitle}</span></div><MoreHorizontal size={17} className="directory-more" /></Link>;
}

function GridIcon() { return <span className="grid-icon"><i /><i /><i /><i /></span>; }
function ActivityIcon({ status }: { status: string }) { return status === "completed" ? <Check size={15} /> : status === "cancelled" ? <X size={15} /> : <Plus size={15} />; }

function BookingRow({ booking, showPayment }: { booking: BookingRecord; showPayment?: boolean }) { return <Link href={`/bookings/${booking.id}`} className="booking-table-row"><span className="booking-name-cell"><span className="booking-type-icon"><Sparkles size={15} /></span><span><strong>{booking.service?.name || "Reservation"}</strong><small>{booking.booking_number}</small></span></span><span className="customer-cell"><span className="customer-avatar">{initials(booking.customer?.name || booking.guest_name || "Guest")}</span><span>{booking.customer?.name || booking.guest_name || "Guest customer"}</span></span><span className="schedule-cell"><strong>{dateLabel(booking.starts_at)}</strong><small>{timeLabel(booking.starts_at)} – {timeLabel(booking.ends_at)}</small></span><StatusBadge status={booking.status} /><span className="payment-cell">{showPayment ? <StatusBadge status={booking.payment_status} payment /> : money(booking.total_amount, booking.currency)}</span><ChevronRight size={16} className="row-arrow" /></Link>; }
function BookingCard({ booking, showPayment }: { booking: BookingRecord; showPayment?: boolean }) { return <Link className="booking-card" href={`/bookings/${booking.id}`}><div className="booking-card-top"><span className="booking-type-icon"><Sparkles size={15} /></span><StatusBadge status={booking.status} /><ChevronRight size={16} /></div><strong>{booking.service?.name || "Reservation"}</strong><span className="booking-card-customer"><UserRound size={14} />{booking.customer?.name || booking.guest_name || "Guest customer"}</span><div className="booking-card-bottom"><span><CalendarDays size={14} />{dateLabel(booking.starts_at)}</span><span><Clock3 size={14} />{timeLabel(booking.starts_at)}</span>{showPayment && <span>{money(booking.total_amount, booking.currency)}</span>}</div></Link>; }
function ScheduleItem({ booking }: { booking: BookingRecord }) { return <Link className="schedule-item" href={`/bookings/${booking.id}`}><time>{timeLabel(booking.starts_at)}</time><span className="schedule-line" /><div><strong>{booking.service?.name || "Reservation"}</strong><span>{booking.customer?.name || booking.guest_name || "Guest customer"}{booking.location?.name ? ` · ${booking.location.name}` : ""}</span></div><StatusBadge status={booking.status} /></Link>; }
function InfoBlock({ icon, label, value, subvalue }: { icon: React.ReactNode; label: string; value: string; subvalue: string }) { return <div className="info-block"><span className="info-icon">{icon}</span><div><span>{label}</span><strong>{value}</strong><small>{subvalue}</small></div></div>; }
function SummaryLine({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) { return <div className="summary-line"><span>{icon}</span><div><small>{label}</small><strong>{value}</strong></div></div>; }
function FlowStep({ title, description, children }: { title: string; description: string; children: React.ReactNode }) { return <div className="flow-step-content"><div className="flow-heading"><span className="eyebrow">Step in your flow</span><h2>{title}</h2><p>{description}</p></div>{children}</div>; }
function SkeletonRows() { return <div className="skeleton-rows">{[1, 2, 3].map((row) => <div key={row}><i /><i /><i /><i /></div>)}</div>; }
function NotificationRow({ title, channels, state }: { title: string; channels: string; state: string }) { return <div className="notification-row"><span className="notification-row-icon"><BellIcon /></span><div><strong>{title}</strong><span>{channels}</span></div><span className={`state-pill ${state === "Active" ? "active" : ""}`}>{state}</span><ChevronRight size={15} /></div>; }
function BellIcon() { return <span className="bell-icon"><i /></span>; }

const directoryConfig: Record<"customers" | "services" | "resources" | "staff", { eyebrow: string; title: string; description: string; action: string; icon: React.ReactNode; emptyTitle: string; emptyDescription: string }> = {
  customers: { eyebrow: "Relationships", title: "Customers", description: "Your customer directory, booking history, and rebooking context.", action: "Add customer", icon: <UserRound size={22} />, emptyTitle: "No customers yet", emptyDescription: "Customers created during booking will appear here." },
  services: { eyebrow: "Catalog", title: "Services", description: "Define what customers can book, how long it takes, and what it costs.", action: "Add service", icon: <Sparkles size={22} />, emptyTitle: "No services yet", emptyDescription: "Create your first service to open availability." },
  resources: { eyebrow: "Capacity", title: "Resources", description: "Rooms, vehicles, equipment, and spaces your team can reserve.", action: "Add resource", icon: <GridIcon />, emptyTitle: "No resources yet", emptyDescription: "Add a reservable resource when a service needs one." },
  staff: { eyebrow: "Team", title: "Staff", description: "Booking providers connected to your OperiX people and schedules.", action: "Add staff", icon: <Users size={22} />, emptyTitle: "No booking staff yet", emptyDescription: "Connect an HR employee or add a provider profile." },
};
